def agent(task, memory):
    if task.startswith("remember:"):
        rest = task.split(":", 1)[1].strip()
        if " is " in rest:
            key, value = rest.split(" is ", 1)
            memory[key.strip()] = value.strip()
            result = f"Stored: {key.strip()} = {value.strip()}"
        else:
            result = "Format: remember: X is Y"
    elif task.startswith("recall:"):
        key = task.split(":", 1)[1].strip()
        result = memory.get(key, "Not found")
    elif task == "list":
        if memory:
            result = ", ".join(f"{k}={v}" for k, v in memory.items())
        else:
            result = "Memory is empty"
    else:
        result = "I don't understand"
    return {"task": task, "result": result}
